#include <ios>
#include <cwchar>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::fpos<std::mbstate_t> position{0};
    std::mbstate_t state{};
    position.state(state);
    position += std::streamoff{4};
    assert(std::streamoff(position) == 4);
    auto copy = position;
    assert(copy - position == 0);
}
